package cn.courselens;

import org.json.*;

final class AiModulePlan {
 final JSONObject operation,expected;final String description;
 private AiModulePlan(JSONObject operation,JSONObject expected,String description){this.operation=operation;this.expected=expected;this.description=description;}
 static boolean supports(String type){return type.endsWith("_task")||type.endsWith("_parcel")||type.equals("open_page")||type.equals("remember_project");}
 static JSONObject parcel(ParcelRecord p)throws Exception{return new JSONObject().put("id",p.id).put("code",p.code).put("station",p.station).put("tracking",p.trackingNumber).put("state",p.state).put("confirmed",p.confirmed).put("updatedAt",p.updatedAt);}
 static AiModulePlan build(JSONObject op,JSONObject context)throws Exception{
  DeepSeekPlan.fields(op,"type","index","value");String type=op.getString("type");JSONObject value=op.optJSONObject("value"),expected=null;
  if(type.equals("remember_project")){if(value==null)throw new IllegalArgumentException("请说明要记住的内容");DeepSeekPlan.fields(value,"text");String memory=value.getString("text").trim();if(memory.isEmpty()||memory.length()>2000)throw new IllegalArgumentException("记忆内容应为1–2000字");return new AiModulePlan(op,context.getJSONObject("project"),"保存到当前项目记忆：\n"+memory);}
  if(type.equals("open_page")){if(value==null)throw new IllegalArgumentException("页面未指定");DeepSeekPlan.fields(value,"page");String page=value.getString("page");if(!java.util.Arrays.asList("timetable","tasks","parcels","settings","exams","term","times","timetables").contains(page))throw new IllegalArgumentException("页面不支持");String[] ids={"timetable","tasks","parcels","settings","exams","term","times","timetables"},labels={"课表","任务","快递","设置","考试记录","开学日期","作息时间","课表管理"};return new AiModulePlan(op,null,"打开"+labels[java.util.Arrays.asList(ids).indexOf(page)]);}
  boolean task=type.endsWith("_task");if(!context.optBoolean(task?"tasks_available":"parcels_available",true))throw new IllegalArgumentException("模块数据尚未就绪");if(!java.util.Arrays.asList("add_task","update_task","delete_task","complete_task","add_parcel","update_parcel","delete_parcel","complete_parcel").contains(type))throw new IllegalArgumentException("不支持此操作");
  if(!type.startsWith("add_")){JSONArray rows=context.getJSONArray(task?"tasks":"parcels");int index=DeepSeekPlan.integer(op,"index",0);if(index<1||index>rows.length())throw new IllegalArgumentException("目标已变化");expected=rows.getJSONObject(index-1);}
  if(type.startsWith("add_")||type.startsWith("update_")){if(value==null)throw new IllegalArgumentException("缺少操作内容");if(task){DeepSeekPlan.fields(value,"title","course","deadline");String title=DeepSeekPlan.str(value,"title",expected==null?"":expected.getString("title")),course=DeepSeekPlan.str(value,"course",expected==null?"手动任务":expected.getString("course")),deadline=DeepSeekPlan.str(value,"deadline",expected==null?"":expected.getString("deadline"));if(title.isEmpty()||course.length()>100)throw new IllegalArgumentException("缺少任务名称或分类过长");if(value.has("deadline")&&(expected==null||!deadline.equals(expected.optString("deadline")))&&!deadline.isEmpty()&&!deadline.equals("截止时间未知")&&!deadline.equals("未提供截止时间"))java.time.LocalDateTime.parse(deadline,java.time.format.DateTimeFormatter.ofPattern("uuuu-MM-dd HH:mm").withResolverStyle(java.time.format.ResolverStyle.STRICT));}else{DeepSeekPlan.fields(value,"code","station","tracking");ParcelRecord p=record(expected,value);ParcelRepository.validate(p);}}
  if(type.equals("complete_parcel")&&!expected.getBoolean("confirmed"))throw new IllegalArgumentException("请先在快递页核对该记录");
  if(!type.startsWith("add_")&&!type.startsWith("update_")&&value!=null)throw new IllegalArgumentException("完成或删除操作不能同时修改字段");
  String label=type.startsWith("add_")?"添加":type.startsWith("update_")?"修改":type.startsWith("delete_")?"删除":"标记完成";return new AiModulePlan(op,expected,label+(task?"任务":"快递")+(expected==null?"":"\n原内容："+summary(expected,task))+(value==null?"":"\n填写内容："+summary(value,task)));
 }
 static String summary(JSONObject value,boolean task){StringBuilder text=new StringBuilder();String[] keys=task?new String[]{"title","course","deadline"}:new String[]{"code","station","tracking"};String[] names=task?new String[]{"名称","分类","截止"}:new String[]{"取件码","地址","运单"};for(int i=0;i<keys.length;i++)if(value.has(keys[i]))text.append(names[i]).append("：").append(value.optString(keys[i])).append("  ");return text.toString().trim();}
 static ParcelRecord record(JSONObject previous,JSONObject value)throws Exception{ParcelRecord p=new ParcelRecord();if(previous!=null){p.id=previous.getLong("id");p.code=previous.getString("code");p.station=previous.getString("station");p.trackingNumber=previous.getString("tracking");p.state=previous.getInt("state");p.confirmed=previous.getBoolean("confirmed");}if(value!=null){p.code=DeepSeekPlan.str(value,"code",p.code);p.station=DeepSeekPlan.str(value,"station",p.station);p.trackingNumber=DeepSeekPlan.str(value,"tracking",p.trackingNumber);}if(previous==null&&p.code.isEmpty())p.state=ParcelRecord.TRANSIT;return p;}
}
